using MHWildsOptimizer.Core.Domain;

namespace MHWildsOptimizer.Api;

/// <summary>
/// The game reference behind the wiki pages (data/wiki.json, generated by tools/build_wiki.py): every skill with what each level
/// does in numbers and where it comes from, every armor set, the common consumables and the meal skills. Loaded on its own, the
/// first time a wiki page opens.
/// </summary>
/// <param name="ItemCategories">The item sections in list order (attack, defense, healing, …).</param>
public sealed record WikiData(
    IReadOnlyList<WikiSkill> Skills, IReadOnlyList<WikiArmorSet> ArmorSets,
    IReadOnlyList<WikiItem>? Items = null, IReadOnlyList<WikiItemCategory>? ItemCategories = null, WikiMeals? Meals = null);

/// <param name="Icon">The skill icon's file name in icons/skills.</param>
/// <param name="WeaponOnly">Only weapons carry it as an innate skill: no decoration, armor piece or charm has it.</param>
/// <param name="GogmaPool">A Gogma Artian weapon can roll this set bonus or group skill.</param>
/// <param name="Effects">What each level does in numbers (curated in data/skill_effects.json); null where nothing is curated yet.</param>
public sealed record WikiSkill(
    int Id, string Name, SkillKind Kind, string Icon, string? Description, int MaxLevel, IReadOnlyList<WikiRank> Ranks,
    bool WeaponOnly, bool GogmaPool, SkillEffects? Effects, WikiSources Sources);

/// <param name="Name">The tier's own name for set and group skills ("Black Eclipse I").</param>
/// <param name="Pieces">Pieces a set or group tier needs.</param>
/// <param name="Description">The game's text with exact numbers (curated in data/skill_effects.json), else the game's own.</param>
/// <param name="Game">The game's own wording where <paramref name="Description"/> differs from it.</param>
public sealed record WikiRank(int Level, string? Name, int? Pieces, string? Description, string? Game = null);

/// <param name="Levels">Effect lines by level ("1", "2", …); for set bonuses tier I and II.</param>
/// <param name="Trigger">When it applies.</param>
/// <param name="Confidence">"high", "medium" or "low".</param>
public sealed record SkillEffects(
    string? Trigger, IReadOnlyDictionary<string, IReadOnlyList<string>> Levels, IReadOnlyList<EffectTable>? Tables,
    IReadOnlyList<string>? Notes, string? Source, string? Confidence);

public sealed record EffectTable(string Title, IReadOnlyList<string> Columns, IReadOnlyList<IReadOnlyList<string>> Rows);

/// <param name="Sets">Armor sets whose pieces carry the set bonus or group skill.</param>
public sealed record WikiSources(
    IReadOnlyList<WikiArmorSource>? Armor, IReadOnlyList<WikiDecorationSource>? Decorations, IReadOnlyList<WikiCharmSource>? Charms,
    IReadOnlyList<WikiWeaponSource>? Weapons, IReadOnlyList<string>? Sets);

/// <param name="Rank">"high" or "low".</param>
public sealed record WikiArmorSource(string Name, string Set, ArmorPieceKind Piece, string Rank, int Rarity, int Level);

public sealed record WikiDecorationSource(string Name, SkillKind Kind, int Slot, int Rarity, string? IconColor, int Level);

/// <summary>A charm line at its highest rank.</summary>
public sealed record WikiCharmSource(string Name, int Rarity, int Level);

/// <param name="Kind">The weapon type's API kind ("great-sword").</param>
public sealed record WikiWeaponSource(string Name, string Kind, int Rarity, int Level);

/// <param name="Rank">"high" or "low".</param>
public sealed record WikiArmorSet(string Name, string Rank, int Rarity, IReadOnlyList<string> SetBonus, string? GroupSkill, IReadOnlyList<WikiArmorPiece> Pieces);

/// <param name="SlotsTranscended">The slots after Armor Transcendence, where it changes them (rarity 5 and 6).</param>
/// <param name="SetBonus">The piece's own set bonuses where the set's pieces differ (Gogmazios).</param>
public sealed record WikiArmorPiece(
    int Id, string Name, ArmorPieceKind Piece, int Rarity, IReadOnlyList<int> Slots, IReadOnlyList<int>? SlotsTranscended,
    IReadOnlyList<SkillGrantDto> Skills, int DefenseBase, int DefenseMax, IReadOnlyDictionary<string, int> Resistances,
    IReadOnlyList<string>? SetBonus);

/// <param name="Key">The <see cref="WikiItem.Category"/> it groups.</param>
/// <param name="About">What the category's items have in common (how they stack).</param>
public sealed record WikiItemCategory(string Key, string Title, string? About);

/// <summary>A consumable (curated in data/item_effects.json) with what it does in numbers.</summary>
/// <param name="Icon">The icon's mhdb kind ("drug"); with <paramref name="IconColor"/> the file icons/items/&lt;kind&gt;-&lt;color&gt;.png.</param>
/// <param name="Description">The game's text.</param>
/// <param name="Boost">The effect in a few words for the overview tables ("Attack +5").</param>
/// <param name="Duration">How long it lasts ("30 min"); null for instant effects.</param>
/// <param name="Stacking">What it does and does not stack with.</param>
/// <param name="Recipes">Each recipe's ingredients (combining them makes one).</param>
/// <param name="UsedIn">Items whose recipes use it.</param>
/// <param name="Related">Other wiki items worth comparing it with.</param>
/// <param name="Confidence">"high", "medium" or "low".</param>
public sealed record WikiItem(
    int Id, string Name, string Category, string Icon, string IconColor, int Rarity, int CarryLimit, string? Description,
    string? Boost, string? Duration, IReadOnlyList<string> Effects, string? Stacking, IReadOnlyList<string>? Notes,
    IReadOnlyList<IReadOnlyList<string>>? Recipes, IReadOnlyList<string>? UsedIn, IReadOnlyList<string>? Related,
    string? Source, string? Confidence);

/// <summary>Meals and the meal skills they give (curated in data/meal_skills.json).</summary>
/// <param name="About">How meals work: what a meal gives, how long it lasts, where the skills come from.</param>
/// <param name="Tables">Meal stats (health, stamina, attack, defense by dish or ingredient).</param>
public sealed record WikiMeals(
    IReadOnlyList<string> About, IReadOnlyList<EffectTable>? Tables, IReadOnlyList<string>? Notes, string? Source,
    IReadOnlyList<WikiMealSkill> Skills);

/// <param name="Icon">The skill-category icon's file name in icons/skills.</param>
/// <param name="Description">The game's text.</param>
/// <param name="Effects">What it does in numbers.</param>
/// <param name="From">The ingredients and meals that give it ("Random" for the random rolls).</param>
public sealed record WikiMealSkill(
    string Name, string Icon, string? Description, IReadOnlyList<string> Effects, IReadOnlyList<string>? Notes, string? From,
    string? Source, string? Confidence);
